import{_ as i,l as n,o as e,c as l,v as o,p as s,x as t,d,i as p,S as h}from"./chunks/framework.InCnrqk-.js";const g=JSON.parse('{"title":"LP 松弛与舍入","description":"","frontmatter":{"title":"LP 松弛与舍入","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/lp-rounding.md","filePath":"cs/lp-rounding.md","lastUpdated":1789023840000}'),P={name:"cs/lp-rounding.md"};function c(_,a,m,u,T,f){const r=n("Mermaid");return e(),l("div",null,[a[1]||(a[1]=o('<h1 id="lp-松弛与舍入" tabindex="-1">LP 松弛与舍入 <a class="header-anchor" href="#lp-松弛与舍入" aria-label="Permalink to &quot;LP 松弛与舍入&quot;">​</a></h1><div class="epigraph"><p>整数约束放松成 $[0,1]$；分数解舍入（随机或按阈值）给出近似，比由 LP/OPT 积分间隙控制。</p><footer>—— 据 Raghavan and Thompson, Randomized Rounding, 1987；CLRS 第 29、35 章；[LP 对偶](/cs/lp-duality) 整理</footer></div><p>上一课<a href="/cs/christofides">Christofides</a>是组合构造。许多问题先写 ILP，松弛为 LP，多项式可解（内点/单纯形）。缺口是舍入：顶点覆盖分数解 \\(x_u\\ge 1/2\\) 则取，\\(2\\)-近似；集合覆盖随机舍入期望 \\(O(\\log n)\\)。不重写单纯形。后课背包 FPTAS 另一路线。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>积分间隙：\\(\\sup\\mathrm{OPT}/\\mathrm{OPT}_{LP}\\)。舍入比不会优于间隙。随机舍入：独立以 \\(x_i\\) 为概率取，Chernoff 管约束破坏再修。依赖舍入、迭代舍入点名。</p><p>缺口是从分数到整数，不是分支定界精确。</p><h3 id="松弛公式要选对" tabindex="-1">松弛公式要选对 <a class="header-anchor" href="#松弛公式要选对" aria-label="Permalink to &quot;松弛公式要选对&quot;">​</a></h3><p>坏 ILP 公式间隙大。顶点覆盖标准 LP 间隙 2。要证明近似须对公式。</p><p><span class="marginnote">Raghavan–Thompson 1987。Goemans–Williamson 最大割 SDP 后课局部搜索旁点名。后课背包伪多项式 \\(\\to\\) FPTAS。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>建模 ILP \\(\\to\\) 松弛 \\(\\to\\) 解 LP \\(\\to\\) 舍入。用对偶拟合证比。检查间隙实例。</p>',11)),(e(),s(h,null,{default:t(()=>[p(r,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20ILP%5B%22ILP%22%5D%20--%3E%20LP%5B%22%E6%9D%BE%E5%BC%9B%22%5D%0A%20%20LP%20--%3E%20RND%5B%22%E9%98%88%E5%80%BC%20%2F%20%E9%9A%8F%E6%9C%BA%E8%88%8D%E5%85%A5%22%5D%0A%20%20RND%20--%3E%20APX%5B%22%CF%81-%E8%BF%91%E4%BC%BC%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=o('<p>无界间隙则此路失败。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>弱对偶：分数 OPT_LP 是整数 OPT 的界。舍入放大变量，约束用概率。与分支定界：那里用界剪枝求精确；这里一次舍入。与 KM 顶标：那是精确对偶，间隙 0。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写 SDP 切平面。不写全部 Raghavan 分析。后课默认：近似可走 LP 舍入，比受间隙限制。下一课背包 FPTAS。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>松弛 + 舍入；比 \\(\\ge\\) 积分间隙。</li><li>随机舍入 + 集中不等式。</li><li>公式选择决定间隙。</li><li>出处：Raghavan and Thompson, 1987；CLRS。</li></ul>',7))])}const A=i(P,[["render",c]]);export{g as __pageData,A as default};
